seen = {}
pi = 0
while True:
    r = apis.venmo.search_users(access_token=venmo_token, query="", page_index=pi, page_limit=20)
    if not r:
        break
    for u in r:
        seen[u["email"]] = (u["first_name"], u["last_name"])
    pi += 1
    if pi > 15:
        break
print("total unique venmo users:", len(seen))
for e,(f,l) in sorted(seen.items()):
    print("  ", f, l, e)
print("Eric Bailey present:", any(v==("Eric","Bailey") for v in seen.values()))
print("Sherry Smith present:", any(v==("Sherry","Smith") for v in seen.values()))
